                 metadata: {
                   name: 'InfraFund',
                   icon:
                     typeof window !== 'undefined'
                       ? `${window.location.origin}/favicon.ico`
                       : '',
                   description: 'InfraFund account access',
                   url:
                     typeof window !== 'undefined' ? window.location.origin : '',
                 },
                 walletConnectProjectId,
