22. type AuthHandler struct {
23. 	svc         service.AuthService
24. 	development bool
25. 	cookieCfg   authCookieConfig
26. }
27. 
28. type authCookieConfig struct {
29. 	sameSite http.SameSite
30. 	domain   string
31. }
32. 
33. func NewAuthHandler(cfg *restcfg.Config, svc service.AuthService) *AuthHandler {
34. 	return &AuthHandler{
35. 		svc:         svc,
36. 		development: cfg.Development,
37. 		cookieCfg: authCookieConfig{
38. 			sameSite: parseSameSite(cfg.CookieSameSite),
39. 			domain:   strings.TrimSpace(cfg.CookieDomain),
40. 		},
41. 	}
42. }
43. 
44. func (a *AuthHandler) Exchange(ctx context.Context,
45. 	in *input.OpenfortExchangeInput,
46. ) (*output.LoginOutput, error) {
47. 	info := client.GetClientInfo(ctx)
48. 
49. 	req := &dto.OpenfortExchangeReq{
50. 		AccessToken:      extractBearerToken(in.Authorization),
51. 		FirstName:        in.Body.FirstName,
52. 		LastName:         in.Body.LastName,
53. 		OrganizationName: in.Body.OrganizationName,
54. 		PhoneNumber:      shared.NewPhoneNumber(in.Body.PhoneNumber),
55. 		Email:            shared.NewEmail(in.Body.Email),
56. 		Type:             object.UserType(in.Body.Type),
57. 		Role:             object.UserRole(in.Body.Role),
58. 	}
59. 
60. 	if req.AccessToken == "" {
61. 		return nil, output.NewErrorOutput(
62. 			errs.NewAppError(errs.BadRequest, "Authorization bearer token is required.", 400),
63. 		)
64. 	}
65. 
66. 	attachClientInfo(info, &req.Audit)
67. 
68. 	resp, err := a.svc.Exchange(ctx, req)
69. 	if err != nil {
70. 		return nil, output.NewErrorOutput(err)
71. 	}
72. 
73. 	return a.createLoginOutput(resp), nil
74. }
75. 
76. func (a *AuthHandler) Me(ctx context.Context,
77. 	_ *input.CurrentUserInput,
78. ) (*output.SuccessOutput[*dto.MeResp], error) {
79. 	userID, err := authorizedUserID(ctx)
80. 	if err != nil {
81. 		return nil, err
82. 	}
83. 
84. 	resp, svcErr := a.svc.Me(ctx, userID)
85. 	if svcErr != nil {
86. 		return nil, output.NewErrorOutput(svcErr)
87. 	}
88. 
89. 	return output.NewSuccessOutput(resp), nil
90. }
91. 
92. func (a *AuthHandler) AccountStatus(ctx context.Context,
93. 	_ *input.CurrentUserInput,
94. ) (*output.SuccessOutput[*dto.AccountStatusResp], error) {
95. 	userID, err := authorizedUserID(ctx)
96. 	if err != nil {
97. 		return nil, err
98. 	}
99. 
100. 	resp, svcErr := a.svc.AccountStatus(ctx, userID)
101. 	if svcErr != nil {
102. 		return nil, output.NewErrorOutput(svcErr)
103. 	}
104. 
105. 	return output.NewSuccessOutput(resp), nil
106. }
