108. func (a *AuthHandler) KycStatus(ctx context.Context,
109. 	_ *input.CurrentUserInput,
110. ) (*output.SuccessOutput[*dto.KycStatusResp], error) {
111. 	userID, err := authorizedUserID(ctx)
112. 	if err != nil {
113. 		return nil, err
114. 	}
115. 
116. 	resp, svcErr := a.svc.KycStatus(ctx, userID)
117. 	if svcErr != nil {
118. 		return nil, output.NewErrorOutput(svcErr)
119. 	}
120. 
121. 	return output.NewSuccessOutput(resp), nil
122. }
123. 
124. func (a *AuthHandler) RefreshAccessToken(ctx context.Context,
125. 	in *input.RefreshTokenInput,
126. ) (*output.SuccessOutput[*dto.RefreshAccessTokenResp], error) {
127. 	resp, err := a.svc.RefreshAccessToken(ctx, in.RefreshToken)
128. 	if err != nil {
129. 		return nil, output.NewErrorOutput(err)
130. 	}
131. 
132. 	return output.NewSuccessOutput(resp), nil
133. }
134. 
135. func (a *AuthHandler) Logout(ctx context.Context,
136. 	in *input.RefreshTokenInput,
137. ) (*output.LogoutOutput, error) {
138. 	if err := a.svc.Logout(ctx, in.RefreshToken); err != nil {
139. 		return nil, output.NewErrorOutput(err)
140. 	}
141. 
142. 	return &output.LogoutOutput{
143. 		Body:      output.NewSuccessEmptyOutput(),
144. 		SetCookie: a.clearRefreshTokenCookie(),
145. 	}, nil
146. }
147. 
148. func authorizedUserID(ctx context.Context) (uuid.UUID, error) {
149. 	userInfo := authctx.GetUserInfoFromContext(ctx)
150. 	if userInfo == nil {
151. 		return uuid.Nil, output.NewErrorOutput(
152. 			errs.NewAppError(errs.Unauthorized, "missing authorized user context", 401),
153. 		)
154. 	}
155. 
156. 	return userInfo.UserID, nil
157. }
158. 
159. func attachClientInfo(info *client.Info, audit *dto.AuditReq) {
160. 	if info == nil {
161. 		return
162. 	}
163. 	audit.IPAddress = info.IP
164. 	audit.UserAgent = info.UserAgent
165. 	audit.Platform = info.Platform
166. 	audit.Browser = info.Browser
167. 	audit.Device = info.Device
168. }
169. 
170. func extractBearerToken(header string) string {
171. 	const bearerPrefix = "Bearer "
172. 	if !strings.HasPrefix(header, bearerPrefix) {
173. 		return ""
174. 	}
175. 
176. 	return strings.TrimSpace(strings.TrimPrefix(header, bearerPrefix))
177. }
178. 
179. func (a *AuthHandler) createRefreshTokenCookie(token string, expiry time.Time) http.Cookie {
180. 	cookie := http.Cookie{
181. 		Name:     "refresh_token",
182. 		Value:    token,
183. 		Secure:   !a.development,
184. 		HttpOnly: true,
185. 		SameSite: a.cookieCfg.sameSite,
186. 		Expires:  expiry,
187. 		Path:     "/",
188. 	}
189. 
190. 	if a.cookieCfg.domain != "" {
191. 		cookie.Domain = a.cookieCfg.domain
192. 	}
193. 
194. 	return cookie
195. }
196. 
197. func (a *AuthHandler) clearRefreshTokenCookie() http.Cookie {
198. 	cookie := http.Cookie{
199. 		Name:     "refresh_token",
200. 		Value:    "",
201. 		Secure:   !a.development,
202. 		HttpOnly: true,
203. 		SameSite: a.cookieCfg.sameSite,
204. 		MaxAge:   -1,
205. 		Path:     "/",
206. 	}
207. 
208. 	if a.cookieCfg.domain != "" {
209. 		cookie.Domain = a.cookieCfg.domain
210. 	}
211. 
212. 	return cookie
213. }
214. 
215. func (a *AuthHandler) createLoginOutput(resp *dto.LoginResp) *output.LoginOutput {
216. 	return &output.LoginOutput{
217. 		SetCookie: a.createRefreshTokenCookie(resp.RefreshToken, resp.RefreshTokenExpiry),
218. 		Body: output.SuccessResponse[*dto.LoginResp]{
219. 			Data: resp,
220. 		},
221. 	}
222. }
223. 
224. func parseSameSite(mode string) http.SameSite {
225. 	switch strings.ToLower(strings.TrimSpace(mode)) {
226. 	case "strict":
227. 		return http.SameSiteStrictMode
228. 	case "none":
229. 		return http.SameSiteNoneMode
230. 	default:
231. 		return http.SameSiteLaxMode
232. 	}
233. }
