1. import { AxiosInstance } from 'axios';
2. import { getAccessToken } from './get-access-token.util';
3. 
4. export const setupInterceptors = (axiosInstance: AxiosInstance): void => {
5.   axiosInstance.interceptors.request.use(
6.     async (config) => {
7.       const token = getAccessToken();
8. 
9.       if (token) {
10.         config.headers['Authorization'] = `Bearer ${token}`;
11.       }
12. 
13.       return config;
14.     },
15.     (error) => {
16.       return Promise.reject(error);
17.     }
18.   );
19. 
20.   axiosInstance.interceptors.response.use(
21.     (response) => {
22.       return response;
23.     },
24.     (error) => {
25.       if (error.response) {
26.         console.error('API Error:', error.response.data);
27.         return Promise.reject(
28.           new Error(error.response.data.message || 'API Error')
29.         );
30.       } else if (error.request) {
31.         console.error('Network Error:', error.request);
32.         return Promise.reject(
33.           new Error('Network error, please try again later')
34.         );
35.       } else {
36.         console.error('Error:', error.message);
37.         return Promise.reject(new Error(error.message));
38.       }
39.     }
40.   );
41. };
