 type UserInfo struct {
 	UserID      uuid.UUID
 	SessionID   uuid.UUID
 	KycVerified bool
 	KybVerified bool
 	Role        object.UserRole
 	Type        object.UserType
 }

 func NewUserInfo(claim *crypto.Claim) (*UserInfo, error) {
 	userID, err := uuid.Parse(claim.UserID)
 	if err != nil {
 		return nil, fmt.Errorf("invalid user ID: %w", err)
 	}

 	sessionID, err := uuid.Parse(claim.SessionID)
 	if err != nil {
 		return nil, fmt.Errorf("invalid session ID: %w", err)
 	}

 	return &UserInfo{
 		UserID:      userID,
 		SessionID:   sessionID,
 		KycVerified: claim.KycVerified,
 		KybVerified: claim.KybVerified,
 		Role:        object.UserRole(claim.Role),
 		Type:        object.UserType(claim.Type),
 	}, nil
 }

 func GetUserInfoFromContext(ctx context.Context) *UserInfo {
 	value, ok := ctx.Value(key.AuthorizedUserInfoKey).(*UserInfo)
 	if !ok {
 		return nil
 	}

 	return value
 }

